preConditionHook:
// HOW LONG HAS THE ALWAYS-IN DIRECTION HELD? This is the 'late in the trend' /
// 'the trend has gone on for dozens of bars' gate that the final-flag and
// triangle rules AND with. R23-10 gives 30 bars for a triangle late in a trend
// and V07-09 50 for a trend whose reversal becomes a large flag; one counter,
// two thresholds, 30 the default. What both sources say about what to EXPECT
// after the pattern is not a condition and is not encoded.
//
// ALWAYS-IN DIRECTION, the standing corpus decision, inlined here because no
// rule file carries it: the direction FLIPS on consecutiveBars consecutive
// STRONG TREND BARS -- body at least bodyFraction of the bar's own range, and
// BOTH tails no more than tailFraction of it -- holds until the opposite flip,
// and is UNDEFINED (aiDir = 0) until the first flip ever. aiBars is 0 on the
// flip bar and counts up from there, so the rule cannot fire until a direction
// exists, which the aiDir != 0 guard makes explicit. The bar-shape test is the
// one ExitOnOppositeStrongTrendBar uses: a strict body direction, the body
// fraction, and both tails.
//
// The flip is written as two guarded blocks and a flipped flag rather than an
// else-if chain, so the twin is statement for statement and the increment
// happens on exactly the bars neither branch took. A bar cannot satisfy both
// branches, so the flag only prevents a double count.
//
// The all-of-N loop starts true and lets any failing bar clear the flag --
// StrongTrendBarRun's arrangement -- so the loop runs unconditionally and
// EasyLanguage's lack of short-circuiting cannot matter. The flags are class
// members and persist across bars, so both are reset at the top.
//
// SAME on both sides, deliberately: this measures the AGE of the direction,
// not the direction itself. A pane that wants the direction as well ANDs the
// always-in rule; this one only says the trend is old.
//
// Deepest bar touched: consecutiveBars - 1.
allBull = true;
allBear = true;
for (int k = 0; k < (int)consecutiveBars; ++k) {
    rng = high[k] - low[k];
    if (el_le(close[k], open[k])) allBull = false;
    if (el_lt(close[k] - open[k], bodyFraction * rng)) allBull = false;
    if (el_gt(high[k] - close[k], tailFraction * rng)) allBull = false;
    if (el_gt(open[k] - low[k], tailFraction * rng)) allBull = false;
    if (el_ge(close[k], open[k])) allBear = false;
    if (el_lt(open[k] - close[k], bodyFraction * rng)) allBear = false;
    if (el_gt(close[k] - low[k], tailFraction * rng)) allBear = false;
    if (el_gt(high[k] - open[k], tailFraction * rng)) allBear = false;
}
flipped = false;
if (allBull && aiDir != 1) {
    aiDir = 1;
    aiBars = 0;
    flipped = true;
}
if (allBear && aiDir != -1 && flipped == false) {
    aiDir = -1;
    aiBars = 0;
    flipped = true;
}
if (flipped == false) aiBars = aiBars + 1;
trendMature = (aiDir != 0) && ((double)aiBars >= minTrendBars);
